window.__PAGE_RUNTIME_PARTIALS__["partials/sb10-guia-07-verificar-operacion-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\u003c!-- Generado por herramientas/generar_guias_mantenimiento.py (2026-10-22) desde el PDF original del\n     instructor (competencia 220501001, RAP 03). No editar a mano: editar mant_specs.py y regenerar. --\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA \u0026middot; FPI\u003c/div\u003e\n      \u003ch2\u003eGu\u0026iacute;a 7 - Verificar la operación del sistema computacional\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinform\u0026aacute;ticos\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha u-hidden\" id=\"sb-ficha-ok\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformaci\u0026oacute;n\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificaci\u0026oacute;n\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentaci\u0026oacute;n\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexi\u0026oacute;n Inicial\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualizaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#materiales\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128193;\u003c/span\u003e Materiales de apoyo\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eGu\u0026iacute;a asignada\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"santa-barbara-10a-guia-07-verificar-operacion.html\" data-current-file=\"santa-barbara-10a-guia-07-verificar-operacion.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128270;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eGu\u0026iacute;a 7\u003c/span\u003e\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003eVerificar operación del sistema | 10A\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\n        \u003cstrong\u003eGu\u0026iacute;a 7 - Verificar la operación del sistema computacional\u003c/strong\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e88 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta Bárbara | Grado 10\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGu\u0026iacute;a 7 | Fase: Ejecución\u003c/div\u003e\n        \u003ch1\u003eVerificar la operación del sistema computacional de acuerdo con los procedimientos técnicos.\u003c/h1\u003e\n        \u003cp\u003eEn esta guía aprenderás a diferenciar el diagnóstico de hardware del de software, a usar herramientas gratuitas o incluidas en Windows (CPU-Z, CrystalDiskInfo, Administrador de dispositivos, Administrador de tareas, Información del sistema y Diagnóstico de memoria), a interpretar sus resultados y a identificar posibles anomalías aplicando un procedimiento técnico.\u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Competencia: Mantener equipos de c\u0026oacute;mputo\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 88 horas\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; C\u0026oacute;digo: 233108 \u0026middot; V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus entregas y respuestas guardadas\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla se marca sola: \u003cstrong\u003eEntregada\u003c/strong\u003e cuando subes la evidencia a Drive y\n            \u003cstrong\u003eGuardada\u003c/strong\u003e cuando guardas tus respuestas. Lo que siga en Pendiente es lo que te falta.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificaci\u0026oacute;n de la Gu\u0026iacute;a\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDatos del Programa de Formaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003eInformaci\u0026oacute;n oficial del programa y la competencia\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominaci\u0026oacute;n del Programa\u003c/td\u003e\u003ctd\u003eT\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eC\u0026oacute;digo del Programa\u003c/td\u003e\u003ctd\u003e233108 \u0026middot; V1\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eAlfabetización Digital, Asesoría Técnica y Ciberseguridad para la Mejora de Actividades Productivas Locales en la Zona de Influencia del CIAS.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003eEjecución\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003eImplementar procesos de soporte técnico básico, personalización de herramientas digitales y orientación en ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e220501001 — Mantener equipos de cómputo según procedimiento técnico.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 03 \u0026mdash; Verificar la operación del sistema computacional de acuerdo con los procedimientos técnicos.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuraci\u0026oacute;n\u003c/td\u003e\u003ctd\u003e88 horas\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata la guía y qué vas a lograr. Léela completa antes de comenzar las actividades.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar esta guía? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee la teoría\u003c/strong\u003e de las secciones de contextualización antes de resolver las actividades.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve cada actividad\u003c/strong\u003e en orden. Escribe tus respuestas en los campos de la guía.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eGuarda tus respuestas\u003c/strong\u003e con el botón de cada actividad. Tu avance queda guardado en este navegador.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega las evidencias\u003c/strong\u003e que lo pidan con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e. Quedan en la carpeta de tu ficha.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e (arriba): te muestra qué llevas Entregado, Guardado y Pendiente.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eBienvenida a la Gu\u0026iacute;a\u003c/h3\u003e\n              \u003cp\u003eConoce el contexto, el alcance y las metas de este recorrido formativo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e¡Bienvenido, aprendiz! Cuando un computador se vuelve lento, se congela o se reinicia solo, no basta con «adivinar» qué le pasa. Un técnico en sistemas necesita diagnosticar: comprobar con herramientas y con un procedimiento ordenado cómo está funcionando cada parte del equipo, comparar lo que encuentra con lo que debería ser normal y decidir con evidencias si el equipo opera bien o presenta una anomalía. Verificar la operación de un sistema computacional evita cambios innecesarios de piezas, protege la información de las personas y permite entregar un equipo en el que se puede confiar.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eEn esta guía usted desarrollará el RAP 03 de la competencia «Mantener equipos de cómputo según procedimiento técnico». Aprenderá a diferenciar el diagnóstico de hardware (procesador, memoria, almacenamiento, dispositivos) del diagnóstico de software (sistema operativo, programas, controladores, licenciamiento), a usar herramientas gratuitas o incluidas en Windows, como CPU-Z, CrystalDiskInfo, el Administrador de dispositivos, el Administrador de tareas, Información del sistema y el Diagnóstico de memoria de Windows, a interpretar los resultados y a identificar posibles anomalías aplicando un procedimiento técnico. El caso guía es la \u003cstrong\u003ePapelería y Miscelánea El Nogal\u003c/strong\u003e (San Pablo de Borbur, Boyacá), cuyo equipo de contabilidad presenta un funcionamiento irregular.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eTrabajará en cuatro momentos: primero reflexionará sobre el caso de El Nogal; luego estudiará los conceptos de diagnóstico y verificación y elaborará un protocolo (una lista ordenada de comprobaciones); después practicará con cada herramienta (preparación, procedimiento, datos, interpretación y evidencia); y finalmente realizará un laboratorio integrador en el que presentará un registro de resultados de diagnóstico del equipo. En esta guía no se repara ni se cambia ninguna pieza: el RAP 03 se trata de comprobar, interpretar y concluir; la documentación formal del mantenimiento corresponde al RAP 04.\u003c/p\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128737; Seguridad durante las prácticas, para cuidar los equipos y la información\u003c/div\u003e\n            \u003col class=\"u-steps-top\"\u003e\n          \u003cli\u003eTrabaje solo en los equipos que el instructor le asigne y con su permiso.\u003c/li\u003e\n          \u003cli\u003eNo abra el equipo ni desconecte nada.\u003c/li\u003e\n          \u003cli\u003eNo use activadores ni programas de páginas no oficiales.\u003c/li\u003e\n          \u003cli\u003eNo formatee, no repare discos y no cambie contraseñas.\u003c/li\u003e\n          \u003cli\u003eNo muestre datos personales en las capturas de pantalla.\u003c/li\u003e\n          \u003cli\u003eSi una herramienta muestra una falla, anótela y avise al instructor, sin intentar arreglarla.\u003c/li\u003e\n            \u003c/ol\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box green u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Lo que necesitas para esta gu\u0026iacute;a\u003c/div\u003e\n            \u003cp\u003eComputador con Windows (de los equipos de práctica asignados por el instructor), acceso a internet, las herramientas CPU-Z y CrystalDiskInfo (gratuitas, instaladas o descargadas desde sus sitios oficiales por el instructor), una suite ofimática (LibreOffice o Microsoft Office) para los registros y el material de apoyo suministrado por el instructor. Lea siempre las instrucciones completas y guarde cada evidencia con un nombre descriptivo. \u003cstrong\u003eSin evidencia, no hay evaluaci\u0026oacute;n.\u003c/strong\u003e\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.1 · ACTIVIDADES DE REFLEXIÓN INICIAL ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 · Actividades de Reflexión Inicial\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de reflexión inicial:\u003c/strong\u003e activa lo que ya sabes. Aquí no se evalúa el acierto, sino tu participación.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eActivar lo que usted ya sabe sobre el funcionamiento de un computador y reconocer que un problema de rendimiento o de almacenamiento debe verificarse con pruebas antes de decidir qué hacer. Metodología pedagógica: aprendizaje basado en problemas (ABP: se aprende resolviendo un caso real), con la técnica activa de lluvia de ideas en equipo. Relación con el RAP: parte de la necesidad de verificar la operación del sistema. Todo el tiempo de reflexión es trabajo directo con el instructor (2 horas).\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-reflexion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Reflexión Inicial\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 2 horas directas\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Papelería y Miscelánea El Nogal, San Pablo de Borbur (Boyacá)\u003c/h3\u003e\n                \u003cp\u003eUna semana después del mantenimiento del equipo de contabilidad, la propietaria llama preocupada: el computador tarda mucho en encender, el programa contable se congela, aparece el aviso de poco espacio en el disco y, a veces, el equipo se reinicia solo. Ella pregunta: ¿el computador está dañado?, ¿hay que comprar otro? Usted será el técnico que verifique, con evidencias, cómo está funcionando realmente el sistema.\u003c/p\u003e\n              \u003c/article\u003e\n          \u003c!-- ───────── Actividad 3.1.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003e«¿Qué le pasa al computador de El Nogal?»\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e En grupos de 3 o 4 personas, respondan mediante lluvia de ideas (no es necesario entregar producto escrito). Recursos: tablero y cuaderno o bitácora. Evidencia: participación registrada por el instructor. Duración: 1 hora directa.\u003c/p\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eLluvia de ideas en grupo (3 o 4 personas)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003cp class=\"intro-text u-note-0\"\u003eNo es necesario entregar un producto escrito por el grupo: registra aquí tus propias respuestas como participante de la discusión.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. ¿Qué problema presenta el equipo? Enumere al menos tres síntomas.\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_311_sintomas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. ¿Qué componentes del computador deben comprobarse (procesador, memoria, almacenamiento, dispositivos, sistema operativo)?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_311_componentes\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. ¿Qué herramientas conocen o podrían usarse para comprobar cada componente?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_311_herramientas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. ¿Cómo verificarían los resultados? ¿Qué datos anotarían para no depender de la memoria?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_311_registro\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. ¿Cómo podrían determinar si lo que observan es una anomalía o un funcionamiento normal?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_311_normal\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"nogal311DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarNogal311\" class=\"btn-save-response\" onclick=\"actStd_save_nogal311()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_nogal311()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusNogal311\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.1.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eSocialización en plenaria\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Compartir el síntoma más preocupante y el componente que comprobaría primero, y cerrar con una idea final. Duración: 1 hora directa.\u003c/p\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eCada grupo comparte en máximo 2 minutos el síntoma más preocupante y el componente que comprobaría primero.\u003c/li\u003e\n                  \u003cli\u003eEl instructor registra en el tablero los síntomas y los agrupa en: hardware, software y almacenamiento.\u003c/li\u003e\n                  \u003cli\u003eEscriba en su bitácora una idea final: ¿por qué es mejor verificar con herramientas y datos que «adivinar» la falla?\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eBitácora de cierre\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Síntoma más preocupante que compartió tu grupo y componente que comprobaría primero\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_312_sintoma_grupo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Idea final: ¿por qué es mejor verificar con herramientas y datos que «adivinar» la falla?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_312_reflexion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"plenaria312DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlenaria312\" class=\"btn-save-response\" onclick=\"actStd_save_plenaria312()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plenaria312()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlenaria312\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.2 · CONTEXTUALIZACIÓN E IDENTIFICACIÓN DE CONOCIMIENTOS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 · Contextualización e Identificación de Conocimientos\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de contextualización:\u003c/strong\u003e aquí están los conceptos que necesitas y construyes tu protocolo de verificación.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eConstruir la base conceptual sobre diagnóstico y verificación, herramientas, fallas frecuentes, interpretación de resultados, licenciamiento y seguridad, y convertirla en un protocolo de verificación propio. Metodología pedagógica: aprendizaje colaborativo con estudio por bloques temáticos. Relación con el RAP: saberes de protocolos de verificación, licenciamiento y software utilitario.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-contexto\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Contextualización\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 16 horas (10 directas + 6 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003c!-- ───────── Actividad 3.2.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEstudio de contenidos de diagnóstico y verificación (Bloques A, B y C)\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión diagnóstica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Estudiar en equipo de 3 los 12 temas de los Bloques A, B y C y consolidar una tabla resumen en PDF: \u003ccode\u003eBloquesABC_RAP03_[TuNombre]_v1.0.pdf\u003c/code\u003e. Duración: 4 horas independientes + 6 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (4 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eEstudie los temas de los Bloques A, B y C con el material de apoyo y los manuales que indique el instructor. Tome apuntes en su bitácora. Llegue a clase con al menos una duda por bloque.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque A — Diagnóstico y verificación del funcionamiento)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eConcepto de diagnóstico y verificación\u003c/td\u003e\u003ctd\u003eQué es diagnosticar, qué es verificar y para qué sirve comprobar el funcionamiento antes y después de una intervención.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eDiagnóstico de hardware\u003c/td\u003e\u003ctd\u003eQué datos revelan el procesador, la memoria RAM, el almacenamiento y los dispositivos; cómo identificar sus características.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eDiagnóstico de software\u003c/td\u003e\u003ctd\u003eRevisión del sistema operativo, controladores, programas de inicio, actualizaciones y estado de la protección.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eFallas frecuentes\u003c/td\u003e\u003ctd\u003eLentitud, calentamiento, ruidos del disco, disco casi lleno, cierres o reinicios inesperados, dispositivos sin controlador: posibles causas y qué comprobar.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eProtocolo de verificación\u003c/td\u003e\u003ctd\u003eDefinición, características y función; cómo se elabora: orden de pasos, herramienta, dato por registrar y criterio de normalidad.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque B — Herramientas e interpretación de resultados)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eCPU-Z\u003c/td\u003e\u003ctd\u003eMuestra qué procesador (nombre, núcleos e hilos), placa base, memoria RAM y tarjeta gráfica tiene el equipo, y la versión de su BIOS (el programa básico de la placa).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eCrystalDiskInfo y S.M.A.R.T.\u003c/td\u003e\u003ctd\u003eEstado de salud del disco (Bueno, Precaución, Malo), temperatura, horas de uso y datos S.M.A.R.T. (el autodiagnóstico del disco). Los nombres pueden variar según el idioma, la versión y el tipo de disco.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eHerramientas de Windows\u003c/td\u003e\u003ctd\u003eAdministrador de dispositivos, Administrador de tareas (Rendimiento e Inicio), Información del sistema (msinfo32), Diagnóstico de memoria de Windows y Seguridad de Windows.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eValor normal vs. anomalía\u003c/td\u003e\u003ctd\u003eComparar el dato obtenido con las especificaciones del equipo y con las otras mediciones. Un dato aislado no basta: se registra, se compara y se interpreta.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque C — Licenciamiento, legalidad y seguridad)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eLicenciamiento de sistemas operativos\u003c/td\u003e\u003ctd\u003eTipos de licencia: OEM (viene incluida con el computador), retail (se compra por separado), volumen (para muchos equipos de una organización) y código abierto (libre, como Linux). Cómo comprobar el estado de activación: Configuración \u0026gt; Sistema \u0026gt; Activación.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eSoftware legal y seguro\u003c/td\u003e\u003ctd\u003eRiesgos de los activadores y de los programas de páginas no oficiales; alternativas legales (licencia original, versiones de evaluación, software libre); descargar solo de sitios oficiales.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eSeguridad durante el diagnóstico\u003c/td\u003e\u003ctd\u003ePedir autorización, guardar el trabajo, no hacer procedimientos que dañen o borren (formatear, reparar discos, cambiar contraseñas) y proteger los datos personales en las evidencias.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eForme un equipo de 3 personas. Repartan los 12 temas (5 del Bloque A + 4 del Bloque B + 3 del Bloque C): 4 temas por integrante.\u003c/li\u003e\n                  \u003cli\u003eDurante la primera hora, cada integrante explica sus temas al equipo (5 minutos por tema) mientras los demás completan sus apuntes.\u003c/li\u003e\n                  \u003cli\u003eEn LibreOffice Calc o Google Sheets, construyan una tabla de 3 columnas: «Tema», «¿Para qué sirve en una verificación?» y «Ejemplo con el caso de El Nogal».\u003c/li\u003e\n                  \u003cli\u003eEl instructor realiza una plenaria de cierre donde cada equipo comparte su fila más importante.\u003c/li\u003e\n                  \u003cli\u003eExporten la tabla a PDF con el nombre \u003cstrong\u003eBloquesABC_RAP03_[TuNombre]_v1.0.pdf\u003c/strong\u003e y compártanla por el medio indicado por el instructor.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eTabla resumen de los Bloques A, B y C en PDF (BloquesABC_RAP03_[TuNombre]_v1.0.pdf) y apuntes previos en la bitácora. Esta actividad alimenta la Actividad 3.2.2 y la evaluación de conocimiento IE-01.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eRegistro guiado del aprendiz\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Reparto del equipo: temas y responsable de cada uno\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_321_reparto\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Temas que estudiaste tú (4 de los 12)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_321_temas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Una duda por bloque (A, B y C) que llevaste a la sesión\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_321_dudas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Tema de tu fila en la tabla resumen\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_321_tema_fila\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. ¿Para qué sirve en una verificación?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_321_paraque\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Ejemplo con el caso de El Nogal\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_321_ejemplo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"bloquesABC321DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloquesABC321\" class=\"btn-save-response\" onclick=\"actStd_save_bloquesABC321()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_bloquesABC321()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloquesABC321\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-bloquesABC321\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.2.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eElaboración del protocolo de verificación\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión diagnóstica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Construir en equipo un protocolo de verificación de una o dos páginas. Duración: 2 horas independientes + 4 horas directas.\u003c/p\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones — sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn equipos de máximo 3 integrantes, revisen sus apuntes de la Actividad 3.2.1 y la lista de síntomas del caso de El Nogal.\u003c/li\u003e\n                  \u003cli\u003eConstruyan un protocolo de verificación de una o dos páginas. Un protocolo es una lista ordenada de comprobaciones: cada fila dice qué se comprueba, con qué herramienta, qué dato se anota y cuándo se considera normal o anomalía. Comprobaciones mínimas: identificar el equipo, procesador, memoria RAM, almacenamiento, dispositivos y controladores, rendimiento, protección y licenciamiento.\u003c/li\u003e\n                  \u003cli\u003eIncluyan una fila de licenciamiento: comprobar el estado de activación en Configuración \u0026gt; Sistema \u0026gt; Activación. No se permite usar activadores.\u003c/li\u003e\n                  \u003cli\u003eIncluyan una fila final de seguridad: autorización del instructor, trabajo guardado y ausencia de datos personales en las capturas.\u003c/li\u003e\n                  \u003cli\u003ePresenten el protocolo al instructor para su revisión; será la guía de trabajo de las etapas 3.3 y 3.4.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\u003ctr\u003e\u003cth\u003eComprobación\u003c/th\u003e\u003cth\u003eHerramienta\u003c/th\u003e\u003cth\u003eDato por registrar / criterio de normalidad\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eMemoria RAM instalada (ejemplo)\u003c/td\u003e\u003ctd\u003eCPU-Z (pestaña Memory)\u003c/td\u003e\u003ctd\u003eAnotar tipo y tamaño. Normal: coincide con la ficha técnica del equipo. Anomalía: es menor o distinta de la ficha.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eProtocolo de verificación del equipo (PDF o DOCX), con comprobaciones, herramientas, datos y criterios, revisado por el instructor. Esta actividad prepara las prácticas de la Actividad 3.3.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eProtocolo de verificación (una fila por comprobación: herramienta — dato por registrar — criterio de normalidad)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Identificación del equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_identificacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Procesador\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_procesador\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Memoria RAM\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_ram\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Almacenamiento\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_almacenamiento\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Dispositivos y controladores\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_dispositivos\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Rendimiento\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_rendimiento\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e7. Protección\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_proteccion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e8. Licenciamiento (Configuración \u003e Sistema \u003e Activación; sin activadores)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_licenciamiento\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e9. Fila final de seguridad (autorización, trabajo guardado, sin datos personales)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_322_seguridad\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"protocolo322DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarProtocolo322\" class=\"btn-save-response\" onclick=\"actStd_save_protocolo322()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_protocolo322()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusProtocolo322\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-protocolo322\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.3 · ACTIVIDADES DE APROPIACIÓN DEL CONOCIMIENTO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 · Actividades de Apropiación del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de apropiación:\u003c/strong\u003e practicas con cada herramienta. Las prácticas no modifican el equipo.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003ePracticar la verificación de cada parte del equipo con herramientas de diagnóstico —procesador y memoria, almacenamiento y herramientas de Windows— y aprender a interpretar los datos que entregan. Metodología pedagógica: práctica guiada con aprendizaje entre pares (uno ejecuta la prueba y otro registra los datos; luego intercambian). Relación con el RAP: ejecuta software utilitario y verifica el funcionamiento del equipo según el procedimiento técnico. Las prácticas no modifican el equipo.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-apropiacion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128218;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Apropiación\u003c/h3\u003e\n              \u003cp\u003e4 actividades · Duración: 36 horas (28 directas + 8 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Papelería y Miscelánea El Nogal, San Pablo de Borbur (Boyacá)\u003c/h3\u003e\n                \u003cp\u003eUna semana después del mantenimiento del equipo de contabilidad, la propietaria llama preocupada: el computador tarda mucho en encender, el programa contable se congela, aparece el aviso de poco espacio en el disco y, a veces, el equipo se reinicia solo. Ella pregunta: ¿el computador está dañado?, ¿hay que comprar otro? Usted será el técnico que verifique, con evidencias, cómo está funcionando realmente el sistema.\u003c/p\u003e\n              \u003c/article\u003e\n          \u003c!-- ───────── Actividad 3.3.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eProcesador, memoria y características del sistema con CPU-Z\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión práctica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Identificar las características del equipo con CPU-Z e interpretarlas. Duración: 2 horas independientes + 8 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (2 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eLea sobre las pestañas de CPU-Z (CPU, Mainboard, Memory, SPD, Graphics) y escriba en su bitácora qué dato espera encontrar en cada una. Si el instructor lo autoriza, revise la guía y el reporte de ejemplo de HWMonitor del material de apoyo.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003e\u003cstrong\u003ePreparación:\u003c/strong\u003e encienda el equipo asignado e inicie sesión con el permiso del instructor. Tenga a mano su protocolo (actividad 3.2.2) y cree una carpeta llamada Evidencias_RAP03_[TuNombre] donde guardará todo. No abra el equipo.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eHerramienta:\u003c/strong\u003e CPU-Z, un programa gratuito que muestra qué componentes tiene el computador (el instructor lo deja instalado o lo descarga del sitio oficial de CPUID). Está en inglés: CPU = procesador, Mainboard = placa base, Memory = memoria RAM, SPD = módulos de memoria, Graphics = tarjeta gráfica. Opcional, solo si el instructor lo tiene disponible: HWMonitor para ver temperaturas (está en el material de apoyo del RAP 01).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eProcedimiento\u003c/strong\u003e (siga los pasos en orden): A. Abra CPU-Z. B. Pestaña CPU: anote nombre, núcleos e hilos. C. Pestaña Mainboard: anote fabricante, modelo y versión de BIOS. D. Pestaña Memory: anote tipo y tamaño. E. Pestaña SPD: anote cuántos módulos de memoria hay. F. Abra Información del sistema (tecla Windows + R, escriba msinfo32 y Enter) y compare los datos. G. Capture cada pestaña (Windows + Shift + S) y guarde las imágenes en su carpeta.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDatos que debe recopilar:\u003c/strong\u003e procesador, núcleos e hilos, placa base y BIOS, tipo y tamaño de la memoria RAM, módulos instalados y tarjeta gráfica. Si usa HWMonitor, las temperaturas en reposo.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eInterpretación:\u003c/strong\u003e compare cada dato con lo que dice la ficha técnica o el manual del equipo. Pregúntese: ¿la memoria es suficiente para el programa contable? ¿CPU-Z y Windows muestran lo mismo? Si algo no coincide, anótelo como posible anomalía.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eEvidencia:\u003c/strong\u003e capturas con nombres descriptivos (por ejemplo, CPUZ_CPU_[TuNombre].png) y una tabla de 3 columnas: Dato | Valor observado | Interpretación (normal o posible anomalía), con una línea por dato.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eTabla de datos del sistema diligenciada (valor e interpretación) y capturas de CPU-Z, en la carpeta de evidencias (PDF o DOCX).\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eTabla de datos del sistema (Dato — Valor observado — Interpretación)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Procesador: nombre, núcleos e hilos\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_331_cpu\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Placa base: fabricante, modelo y versión de BIOS\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_331_placa\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Memoria RAM: tipo y tamaño\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_331_memoria\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Módulos de memoria instalados (pestaña SPD)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_331_modulos\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Tarjeta gráfica\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_331_grafica\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Comparación con Información del sistema (msinfo32): ¿CPU-Z y Windows muestran lo mismo?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_331_msinfo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e7. Interpretación: ¿la memoria es suficiente para el programa contable? Posibles anomalías\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_331_interpretacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"cpuz331DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarCpuz331\" class=\"btn-save-response\" onclick=\"actStd_save_cpuz331()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_cpuz331()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusCpuz331\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-cpuz331\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEstado del almacenamiento con CrystalDiskInfo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión práctica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Verificar la salud y el espacio del almacenamiento (práctica solo de lectura). Duración: 3 horas independientes + 8 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (3 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eInvestigue qué significa S.M.A.R.T., qué indican los estados Bueno, Precaución y Malo de CrystalDiskInfo y por qué un disco «casi lleno» no es lo mismo que un disco «enfermo». Anote tres atributos o datos que consultará (por ejemplo: estado de salud, temperatura, horas de encendido, sectores reasignados o pendientes).\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003e\u003cstrong\u003ePreparación:\u003c/strong\u003e cierre los programas y guarde su trabajo. Con el instructor, identifique el disco del equipo (HDD o SSD) y su capacidad. Esta práctica es solo de lectura: no formatee, no repare ni escriba en el disco.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eHerramienta:\u003c/strong\u003e CrystalDiskInfo, un programa gratuito que muestra la «salud» de los discos (el instructor lo deja instalado o lo descarga del sitio oficial del autor).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eProcedimiento\u003c/strong\u003e (siga los pasos en orden): a) Abra CrystalDiskInfo. b) Anote modelo, capacidad e interfaz del disco. c) Anote el estado de salud (Bueno, Precaución o Malo) y la temperatura. d) Anote las horas de encendido y, si aparecen, los datos de sectores reasignados o pendientes. e) Abra el Explorador de archivos \u0026gt; Este equipo y anote el espacio libre de cada unidad. f) Capture la ventana principal de CrystalDiskInfo y la de Este equipo.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDatos que debe recopilar:\u003c/strong\u003e modelo y capacidad, estado de salud, temperatura, horas de encendido, datos de sectores (si aparecen) y espacio total, libre y usado.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eInterpretación:\u003c/strong\u003e Bueno significa que el disco no muestra alertas. Precaución o Malo es una anomalía: avise de inmediato al instructor y no intente repararlo. Un disco casi lleno puede hacer lento el equipo sin estar dañado: «lleno» y «enfermo» no es lo mismo. Los datos pueden variar según el disco; ante una duda, pregunte al instructor.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eEvidencia:\u003c/strong\u003e capturas de CrystalDiskInfo y del espacio por unidad, y una tabla de 3 columnas (Dato | Valor observado | Interpretación) con una línea por dato. Si hay una alerta: una nota de reporte al instructor, sin intervenir el disco.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eTabla de verificación del almacenamiento (valor e interpretación) y capturas de CrystalDiskInfo y del espacio por unidad, en la carpeta de evidencias (PDF o DOCX).\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eTabla de verificación del almacenamiento (Dato — Valor observado — Interpretación)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Modelo, capacidad e interfaz del disco\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_332_disco\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Estado de salud (Bueno, Precaución o Malo) y temperatura\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_332_salud\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Horas de encendido y datos de sectores reasignados o pendientes (si aparecen)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_332_horas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Espacio total, libre y usado de cada unidad (Este equipo)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_332_espacio\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Interpretación: ¿el disco está «lleno», «enfermo», ambos o ninguno?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_332_interpretacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Nota de reporte al instructor (solo si hubo una alerta)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_332_reporte\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"crystal332DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarCrystal332\" class=\"btn-save-response\" onclick=\"actStd_save_crystal332()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_crystal332()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusCrystal332\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-crystal332\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.3 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.3\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eDispositivos, rendimiento y memoria con herramientas de Windows\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión práctica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Verificar dispositivos, rendimiento, protección, activación y memoria con herramientas de Windows. Duración: 3 horas independientes + 10 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (3 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eRepase dónde se abren el Administrador de dispositivos, el Administrador de tareas, Información del sistema y el Diagnóstico de memoria de Windows, y qué dato esperaría ver en cada uno. Escriba una pregunta de verificación para cada herramienta.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003e\u003cstrong\u003ePreparación:\u003c/strong\u003e guarde y cierre su trabajo. El Diagnóstico de memoria de Windows reinicia el equipo: ejecútelo solo con permiso del instructor y en el equipo de práctica. Siga guardando todo en su carpeta de evidencias.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eHerramienta:\u003c/strong\u003e Administrador de dispositivos (clic derecho en el botón Inicio); Administrador de tareas (Ctrl + Shift + Esc); Información del sistema (Windows + R, escriba msinfo32); Diagnóstico de memoria de Windows (Windows + R, escriba mdsched); Seguridad de Windows (búsquela en el menú Inicio); y Configuración \u0026gt; Sistema \u0026gt; Activación para ver el estado de la licencia.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eProcedimiento\u003c/strong\u003e (siga los pasos en orden): a) Administrador de dispositivos: revise si algún dispositivo tiene un símbolo de advertencia. b) Administrador de tareas: observe el uso de CPU, memoria y disco en reposo y con el programa contable abierto; revise la pestaña Inicio. c) Información del sistema: anote la versión del sistema, la BIOS y la memoria. d) Seguridad de Windows: verifique que la protección esté activa. e) Activación: anote el estado. f) Con permiso del instructor, ejecute el Diagnóstico de memoria y anote el resultado al reiniciar.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eDatos que debe recopilar:\u003c/strong\u003e dispositivos con advertencia (si existen), porcentajes de uso de CPU, memoria y disco, versión del sistema, estado de la protección y de la activación, y resultado del diagnóstico de memoria.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eInterpretación:\u003c/strong\u003e como referencia de este curso, un uso de memoria o disco mayor al 85 % de forma sostenida y con pocos programas abiertos es una posible anomalía; compare con los datos de 3.3.1 y 3.3.2. Un dispositivo con advertencia indica un problema de controlador: se anota y se reporta. Una activación no válida se anota como hallazgo de licenciamiento; no se corrige con activadores.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003eEvidencia:\u003c/strong\u003e capturas de cada herramienta utilizada y una tabla de 3 columnas (Dato | Valor observado | Interpretación) con una línea por dato.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eTabla de verificación con herramientas de Windows diligenciada (valor e interpretación) y capturas de cada herramienta, en la carpeta de evidencias (PDF o DOCX).\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eTabla de verificación con herramientas de Windows (Dato — Valor observado — Interpretación)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Administrador de dispositivos: dispositivos con advertencia (si existen)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_333_dispositivos\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Administrador de tareas: uso de CPU, memoria y disco en reposo y con el programa contable abierto; pestaña Inicio\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_333_rendimiento\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Información del sistema: versión del sistema, BIOS y memoria\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_333_msinfo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Seguridad de Windows: estado de la protección\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_333_proteccion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Activación: estado de la licencia\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_333_activacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Diagnóstico de memoria de Windows (con permiso del instructor): resultado al reiniciar\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_333_memoria_diag\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e7. Interpretación (referencia del curso: uso sostenido mayor al 85 % con pocos programas abiertos = posible anomalía)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_333_interpretacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"windows333DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarWindows333\" class=\"btn-save-response\" onclick=\"actStd_save_windows333()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_windows333()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusWindows333\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-windows333\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003c!-- ───────── Actividad 3.3.4 (la aplica el instructor) ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.4\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEvaluación de conocimiento: cuestionario IE-01\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eEvaluación\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003eEl instructor aplica de forma individual el cuestionario IE-01. Tiene 15 preguntas: 10 de selección múltiple (una sola respuesta correcta) y 5 de respuesta corta (escriba las ideas clave con sus propias palabras) sobre diagnóstico, verificación, herramientas, interpretación, licenciamiento y seguridad. Puede consultar su bitácora solo si el instructor lo permite. Relación con el RAP: evidencia de conocimiento. Duración: 2 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eCuestionario IE-01 resuelto de forma individual. El instructor lo valora con el instrumento IE-01. Esta actividad se realiza en clase con el instructor: no se responde ni se entrega en el portal.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv id=\"ie01334GradeMount\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.4 · ACTIVIDADES DE TRANSFERENCIA DEL CONOCIMIENTO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 · Actividades de Transferencia del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de transferencia:\u003c/strong\u003e verificas el equipo completo y presentas tu registro de resultados.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eAplicar de forma integral y segura la verificación de la operación de un equipo: identificarlo, ejecutar las herramientas, interpretar los resultados y determinar su estado de funcionamiento, presentando evidencias verificables. Metodología pedagógica: aprendizaje basado en problemas (ABP) con trabajo colaborativo. Relación con el RAP: integra los criterios de evaluación del RAP 03. No se exigen reparaciones ni procedimientos destructivos.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-transferencia\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Transferencia\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 34 horas (26 directas + 8 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Papelería y Miscelánea El Nogal, San Pablo de Borbur (Boyacá)\u003c/h3\u003e\n                \u003cp\u003eUna semana después del mantenimiento del equipo de contabilidad, la propietaria llama preocupada: el computador tarda mucho en encender, el programa contable se congela, aparece el aviso de poco espacio en el disco y, a veces, el equipo se reinicia solo. Ella pregunta: ¿el computador está dañado?, ¿hay que comprar otro? Usted será el técnico que verifique, con evidencias, cómo está funcionando realmente el sistema.\u003c/p\u003e\n              \u003c/article\u003e\n          \u003c!-- ───────── Actividad 3.4.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eLaboratorio integrador: verificación de la operación del equipo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Verificar de forma integral la operación del equipo asignado y reunir evidencias verificables. Duración: 5 horas independientes + 18 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (5 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eRepase su protocolo y las tablas de la Actividad 3.3, prepare la carpeta de evidencias y organice el orden en que ejecutará las comprobaciones.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn equipos de máximo 3 integrantes, reciban del instructor el equipo asignado (el del caso u otro equivalente) y confirmen que enciende y permite iniciar sesión, sin abrirlo. Repartan roles: uno ejecuta las pruebas, otro anota los datos y otro captura las pantallas; roten los roles con cada herramienta. El laboratorio se hace en varias sesiones: el instructor indicará qué avance se espera en cada una.\u003c/li\u003e\n                  \u003cli\u003eIdentifiquen el equipo: marca, modelo, sistema operativo y versión, y registren la fecha y hora de la prueba.\u003c/li\u003e\n                  \u003cli\u003eComprueben sus características con CPU-Z (procesador, placa base, memoria) y contrástenlas con Información del sistema.\u003c/li\u003e\n                  \u003cli\u003eEjecuten CrystalDiskInfo y verifiquen el almacenamiento: estado de salud, temperatura y espacio libre por unidad.\u003c/li\u003e\n                  \u003cli\u003eComprueben la memoria y el procesador con el Administrador de tareas y, con autorización del instructor, con el Diagnóstico de memoria de Windows.\u003c/li\u003e\n                  \u003cli\u003eRevisen dispositivos y controladores, protección de Windows y estado de activación.\u003c/li\u003e\n                  \u003cli\u003eIdentifiquen las posibles anomalías, contrasten los datos entre herramientas e interpreten los resultados con los criterios de su protocolo.\u003c/li\u003e\n                  \u003cli\u003eDeterminen el estado de funcionamiento del equipo (funciona normalmente, funciona con observaciones o requiere atención) y propongan una recomendación segura, sin intervenir el equipo.\u003c/li\u003e\n                  \u003cli\u003eReúnan las evidencias verificables: capturas legibles, tablas diligenciadas y notas de las pruebas, con nombres descriptivos.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eEvidencias de las pruebas realizadas (capturas y tablas) organizadas en la carpeta Evidencias_RAP03_[TuNombre]. Se valora el desempeño con la lista de chequeo IE-02.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eRegistro del laboratorio integrador\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Roles del equipo y rotación por herramienta\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_341_roles\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Identificación del equipo: marca, modelo, sistema operativo y versión; fecha y hora de la prueba\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_341_identificacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Características con CPU-Z contrastadas con Información del sistema\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_341_caracteristicas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Almacenamiento con CrystalDiskInfo: salud, temperatura y espacio libre por unidad\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_341_almacenamiento\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Memoria y procesador (Administrador de tareas y, con autorización, Diagnóstico de memoria)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_341_memoria_cpu\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Dispositivos y controladores, protección de Windows y estado de activación\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_341_dispositivos_seguridad\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e7. Posibles anomalías e interpretación según los criterios del protocolo\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_341_anomalias\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e8. Estado de funcionamiento (normal, con observaciones o requiere atención) y recomendación segura\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_341_estado\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"integrador341DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarIntegrador341\" class=\"btn-save-response\" onclick=\"actStd_save_integrador341()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_integrador341()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusIntegrador341\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-integrador341\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.4.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eRegistro de resultados de diagnóstico y sustentación\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Elaborar el registro de resultados de diagnóstico del sistema computacional y sustentarlo en el aula. Duración: 3 horas independientes + 8 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (3 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eElaboren el borrador del registro de resultados de diagnóstico con los datos del laboratorio y preparen una sustentación de máximo 8 minutos.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eCon los datos del laboratorio, elaboren el «Registro de resultados de diagnóstico del sistema computacional» con estas secciones: a) Identificación del equipo. b) Herramientas utilizadas. c) Componentes verificados. d) Resultados obtenidos. e) Evidencias de las pruebas (capturas legibles y sin datos personales). f) Interpretación técnica (qué significa cada resultado). g) Anomalías identificadas (o «no se identificaron»). h) Conclusión del funcionamiento y recomendación segura. Es un registro de las pruebas y sus resultados; no es el informe formal de mantenimiento (hoja de vida, orden de trabajo), que se trabaja en el RAP 04.\u003c/li\u003e\n                  \u003cli\u003eIncluyan en cada sección las capturas o tablas del laboratorio y asegúrense de que los datos sean coherentes con las pruebas realizadas.\u003c/li\u003e\n                  \u003cli\u003eSustenten el registro ante el instructor y sus compañeros (máximo 8 minutos por equipo). Participan todos los integrantes y explican qué verificaron, qué encontraron, cómo interpretan los resultados y cuál es la conclusión sobre el funcionamiento.\u003c/li\u003e\n                  \u003cli\u003eEntreguen el registro en formato digital (PDF o DOCX) con un nombre descriptivo. La sustentación no se publica en plataformas externas: se presenta en el aula.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eRegistro de resultados de diagnóstico del sistema computacional (PDF o DOCX), con las evidencias de las pruebas, y la sustentación en el aula. Se valora con la lista de chequeo de producto IE-03.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eBorrador del registro de resultados (secciones a–h)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003ea) Identificación del equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_342_a_identificacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eb) Herramientas utilizadas\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_342_b_herramientas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003ec) Componentes verificados\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m3_342_c_componentes\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003ed) Resultados obtenidos\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_342_d_resultados\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003ee) Evidencias de las pruebas (lista de capturas y tablas, sin datos personales)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_342_e_evidencias\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003ef) Interpretación técnica (qué significa cada resultado)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m3_342_f_interpretacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eg) Anomalías identificadas (o «no se identificaron»)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_342_g_anomalias\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eh) Conclusión del funcionamiento y recomendación segura\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m3_342_h_conclusion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"registro342DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarRegistro342\" class=\"btn-save-response\" onclick=\"actStd_save_registro342()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_registro342()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusRegistro342\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-registro342\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ MATERIALES DE APOYO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"materiales\" class=\"section-title\"\u003eMateriales de Apoyo\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eConsulta aquí\u003c/strong\u003e los documentos de referencia y las herramientas que necesitas para las actividades de esta guía.\u003c/p\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-teal\"\u003e\u0026#128193;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDocumentos y herramientas\u003c/h3\u003e\n              \u003cp\u003eMaterial de apoyo suministrado por el instructor\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\u003cth\u003eMaterial\u003c/th\u003e\u003cth\u003eActividad\u003c/th\u003e\u003cth\u003eEnlace\u003c/th\u003e\u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eManual de usuario de HWMonitor\u003c/td\u003e\u003ctd\u003e3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/HWMonitor_Manual_Usuario.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eReporte de ejemplo con HWMonitor\u003c/td\u003e\u003ctd\u003e3.3.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/Anexo_Reporte_Ejemplo_HWMonitor.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128295; Herramientas de diagnóstico (Actividades 3.3.1 a 3.4.1)\u003c/div\u003e\n            \u003cp\u003eDescárguelas solo desde el sitio oficial: \u003ca href=\"https://www.cpuid.com/softwares/cpu-z.html\" target=\"_blank\" rel=\"noopener\"\u003eCPU-Z\u003c/a\u003e · \u003ca href=\"https://crystalmark.info/en/software/crystaldiskinfo/\" target=\"_blank\" rel=\"noopener\"\u003eCrystalDiskInfo\u003c/a\u003e · \u003ca href=\"https://www.cpuid.com/softwares/hwmonitor.html\" target=\"_blank\" rel=\"noopener\"\u003eHWMonitor\u003c/a\u003e (opcional). Las herramientas de Windows (Administrador de dispositivos, Administrador de tareas, msinfo32, mdsched, Seguridad de Windows) ya vienen incluidas.\u003c/p\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128194; Material de apoyo que entrega el instructor\u003c/div\u003e\n            \u003cp\u003eEstos documentos del material de apoyo de la gu\u0026iacute;a todav\u0026iacute;a no est\u0026aacute;n publicados en el portal. Sol\u0026iacute;citalos a tu instructor:\u003c/p\u003e\n            \u003cul class=\"u-steps-top\"\u003e\u003cli\u003eManual de Mantenimiento de Computadores (Hardware y Software)\u003c/li\u003e\u003cli\u003eManual de Solución de Fallas — HP Compaq dc5700 (Escritorio)\u003c/li\u003e\u003c/ul\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ EVIDENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003ePlanteamiento de Evidencias para la Evaluaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eResumen de lo que debes entregar:\u003c/strong\u003e usa esta sección como lista de chequeo final.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--entrega\"\u003e\u003cdiv class=\"gnote__label\"\u003e📦 Antes de entregar, revisa\u003c/div\u003e\n        \u003cul\u003e\n          \u003cli\u003eRespondiste todas las actividades que se piden como evidencia.\u003c/li\u003e\n          \u003cli\u003eTus archivos tienen tu nombre y número de ficha.\u003c/li\u003e\n          \u003cli\u003eSubiste cada evidencia con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e y la ves marcada como \u003cstrong\u003eEntregada\u003c/strong\u003e en tu control de avance.\u003c/li\u003e\n        \u003c/ul\u003e\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eTabla de Evidencias del Proceso Formativo\u003c/h3\u003e\n              \u003cp\u003e3 evidencias: conocimiento, desempe\u0026ntilde;o y producto\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\u003cth\u003eActividad de Aprendizaje\u003c/th\u003e\u003cth\u003eEvidencias\u003c/th\u003e\u003cth\u003eCriterios\u003c/th\u003e\u003cth\u003eInstrumento\u003c/th\u003e\u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.2.1 + 3.2.2 + 3.3.4 — Estudio de contenidos, protocolo de verificación y evaluación de conocimiento\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eCONOCIMIENTO:\u003c/strong\u003e cuestionario sobre protocolos de verificación, herramientas de diagnóstico de hardware y software, interpretación de resultados, licenciamiento y seguridad durante el diagnóstico.\u003c/td\u003e\n                  \u003ctd\u003eEjecuta software utilitario según requerimientos del cliente y normatividad. Verifica el funcionamiento del equipo, según el manual de operación.\u003c/td\u003e\n                  \u003ctd\u003eIE-01 — Cuestionario de conocimiento (con clave de respuestas del instructor)\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.3.1 + 3.3.2 + 3.3.3 + 3.4.1 — Prácticas con CPU-Z, CrystalDiskInfo y herramientas de Windows, y laboratorio integrador\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eDESEMPEÑO:\u003c/strong\u003e ejecución de las pruebas de diagnóstico y verificación del sistema computacional en un equipo real, aplicando el procedimiento técnico y las medidas de seguridad.\u003c/td\u003e\n                  \u003ctd\u003eEjecuta software utilitario según requerimientos del cliente y normatividad. Verifica el funcionamiento del equipo, según el manual de operación.\u003c/td\u003e\n                  \u003ctd\u003eIE-02 — Lista de chequeo de desempeño\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.4.2 — Registro de resultados de diagnóstico y sustentación\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003ePRODUCTO:\u003c/strong\u003e registro de resultados de diagnóstico del sistema computacional, con herramientas utilizadas, componentes verificados, resultados, evidencias, interpretación, anomalías y conclusión del funcionamiento.\u003c/td\u003e\n                  \u003ctd\u003eImplementa acciones correctivas según las fallas y procedimientos técnicos establecidos (en esta guía: propone y registra una acción segura, sin reparar el equipo). Verifica el funcionamiento del equipo, según el manual de operación.\u003c/td\u003e\n                  \u003ctd\u003eIE-03 — Lista de chequeo de producto\u003c/td\u003e\n                \u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ GLOSARIO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de T\u0026eacute;rminos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-orange\"\u003e\u0026#128214;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eConceptos clave\u003c/h3\u003e\n              \u003cp\u003e16 t\u0026eacute;rminos t\u0026eacute;cnicos\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary-list\"\u003e\n            \u003cdt\u003eDiagnóstico\u003c/dt\u003e\u003cdd\u003eProceso de identificar, mediante pruebas y herramientas, el estado de funcionamiento de un equipo y las posibles causas de una falla.\u003c/dd\u003e\n            \u003cdt\u003eVerificación del funcionamiento\u003c/dt\u003e\u003cdd\u003eComprobación, con un procedimiento y datos registrados, de que el equipo opera de acuerdo con lo esperado.\u003c/dd\u003e\n            \u003cdt\u003eAnomalía\u003c/dt\u003e\u003cdd\u003eDato o comportamiento que se aparta de lo normal esperado para el equipo y que debe registrarse y reportarse.\u003c/dd\u003e\n            \u003cdt\u003eProtocolo de verificación\u003c/dt\u003e\u003cdd\u003eLista ordenada de comprobaciones, con herramienta, dato por registrar y criterio de normalidad, que permite repetir una verificación de forma consistente.\u003c/dd\u003e\n            \u003cdt\u003eS.M.A.R.T.\u003c/dt\u003e\u003cdd\u003eSistema de autodiagnóstico de los discos que reporta indicadores de su estado de salud, como temperatura, horas de uso y sectores problemáticos.\u003c/dd\u003e\n            \u003cdt\u003eCPU-Z\u003c/dt\u003e\u003cdd\u003ePrograma gratuito que muestra información del procesador, la placa base, la memoria y los gráficos de un equipo.\u003c/dd\u003e\n            \u003cdt\u003eCrystalDiskInfo\u003c/dt\u003e\u003cdd\u003ePrograma gratuito que muestra el estado de salud, la temperatura y los atributos S.M.A.R.T. de los discos de almacenamiento.\u003c/dd\u003e\n            \u003cdt\u003eAdministrador de dispositivos\u003c/dt\u003e\u003cdd\u003eHerramienta de Windows que lista los dispositivos del equipo y señala los que presentan problemas de controlador.\u003c/dd\u003e\n            \u003cdt\u003eControlador (driver)\u003c/dt\u003e\u003cdd\u003eSoftware que permite al sistema operativo comunicarse con un componente de hardware.\u003c/dd\u003e\n            \u003cdt\u003eRendimiento\u003c/dt\u003e\u003cdd\u003eMedida de qué tan bien responde el equipo; se observa, por ejemplo, con el uso de CPU, memoria y disco.\u003c/dd\u003e\n            \u003cdt\u003eLicenciamiento\u003c/dt\u003e\u003cdd\u003eCondiciones legales de uso del software; el estado de activación de Windows se consulta en Configuración \u0026gt; Sistema \u0026gt; Activación.\u003c/dd\u003e\n            \u003cdt\u003eSoftware utilitario\u003c/dt\u003e\u003cdd\u003eProgramas de apoyo, como las herramientas de diagnóstico y de seguridad, que facilitan la verificación y el mantenimiento lógico de un equipo.\u003c/dd\u003e\n            \u003cdt\u003eOEM, retail y volumen\u003c/dt\u003e\u003cdd\u003eTipos de licencia de Windows: OEM viene incluida con el computador, retail se compra por separado y volumen se usa para muchos equipos de una organización.\u003c/dd\u003e\n            \u003cdt\u003eCaptura de pantalla\u003c/dt\u003e\u003cdd\u003eImagen de lo que se ve en la pantalla; en Windows se toma con las teclas Windows + Shift + S.\u003c/dd\u003e\n            \u003cdt\u003eBitácora\u003c/dt\u003e\u003cdd\u003eCuaderno o documento donde el aprendiz anota apuntes, datos y observaciones de su trabajo.\u003c/dd\u003e\n            \u003cdt\u003eCarpeta de evidencias\u003c/dt\u003e\u003cdd\u003eCarpeta del computador donde el aprendiz guarda, con nombres descriptivos, las capturas y tablas de sus prácticas.\u003c/dd\u003e\n          \u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ REFERENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes Bibliogr\u0026aacute;ficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-purple\"\u003e\u0026#128279;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eFuentes oficiales y normativas\u003c/h3\u003e\n              \u003cp\u003e10 referencias para consulta\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references-list u-refs\"\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje — SENA. \u003cem\u003eDiseño Curricular Técnico en Sistemas Teleinformáticos\u003c/em\u003e, versión 233108 V1. SENA, Regional Boyacá.\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje — SENA. \u003cem\u003eProyecto Formativo 3478260 — Alfabetización Digital, Asesoría Técnica y Ciberseguridad para la Mejora de Actividades Productivas Locales en la Zona de Influencia del CIAS\u003c/em\u003e. Regional Boyacá.\u003c/li\u003e\n            \u003cli\u003eCisco Networking Academy. \u003cem\u003eIT Essentials: PC Hardware and Software (v8.0)\u003c/em\u003e. \u003ca href=\"https://www.netacad.com\" target=\"_blank\" rel=\"noopener\"\u003enetacad.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eCPUID. \u003cem\u003eCPU-Z: System information software\u003c/em\u003e. \u003ca href=\"https://www.cpuid.com/softwares/cpu-z.html\" target=\"_blank\" rel=\"noopener\"\u003ecpuid.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eCrystal Dew World. \u003cem\u003eCrystalDiskInfo: HDD/SSD utility software\u003c/em\u003e. \u003ca href=\"https://crystalmark.info/en/software/crystaldiskinfo/\" target=\"_blank\" rel=\"noopener\"\u003ecrystalmark.info\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMicrosoft. \u003cem\u003emsinfo32\u003c/em\u003e. Microsoft Learn. \u003ca href=\"https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/msinfo32\" target=\"_blank\" rel=\"noopener\"\u003elearn.microsoft.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMicrosoft Support. \u003cem\u003eVirus and threat protection in the Windows Security app\u003c/em\u003e. \u003ca href=\"https://support.microsoft.com/windows/virus-and-threat-protection-in-the-windows-security-app-1362f4cd-d71a-b52a-0b66-c2820032b65e\" target=\"_blank\" rel=\"noopener\"\u003esupport.microsoft.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje — SENA. \u003cem\u003eBiblioteca Virtual SENA\u003c/em\u003e. \u003ca href=\"https://biblioteca.sena.edu.co\" target=\"_blank\" rel=\"noopener\"\u003ebiblioteca.sena.edu.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMaterial de apoyo del RAP 03: Manual de Mantenimiento de Computadores (Hardware y Software); Manual de Solución de Fallas — HP Compaq dc5700 (Escritorio); HWMonitor (manual y reporte de ejemplo).\u003c/li\u003e\n            \u003cli\u003eGuía de aprendizaje de referencia: Guía 4 V4 — Software de diagnóstico (Luz Mary Useche Salgado, 2021; actualizaciones 2023), de la cual se tomaron y adaptaron los contenidos del RAP 03.\u003c/li\u003e\n          \u003c/ol\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
